    return "---\nid: projects-sdd-examples-audit-smoke-rs\nfill_sections: [tests, changes]\ncapability_refs:\n  - id: existing-project-standardization\n    role: primary\n    gap: cb-and-cold-verification-gates\n    claim: cb-and-cold-verification-gates\n    coverage: full\n    rationale: \"Codegen/audit validation TDs implement CB and cold verification gates for production readiness.\"\n---\n\n# Standardized apps/agentic-workflow/examples/audit_smoke.rs\n\n## Tests\n<!-- type: tests lang: yaml -->\n\n```yaml\nfile_preamble: |\n  //! Ad-hoc smoke test for the audit primitives. Run with\n  //! `cargo run -q -p sdd --example audit_smoke`.\ntests:\n  - name: main\n    test: false\n    attributes: []\n    body: |\n      use agentic_workflow::generate::audit::{audit_file, audit_markers, ReportKind};\n      use std::path::Path;\n\n      let manifest_dir = Path::new(env!(\"CARGO_MANIFEST_DIR\"));\n      let root = manifest_dir\n          .parent()\n          .and_then(Path::parent)\n          .expect(\"apps/agentic-workflow should live under <repo>/apps/agentic-workflow\");\n      let files = [\n          \"projects/mamba/mambalibs/httpkit/src/http_exception.rs\",\n          \"projects/mamba/mambalibs/httpkit/src/health.rs\",\n          \"projects/mamba/mambalibs/httpkit/src/request_response.rs\",\n          \"projects/mamba/mambalibs/httpkit/src/lib.rs\",\n      ];\n\n      let mut total_blocks = 0;\n      let mut clean = 0;\n      let mut drift = 0;\n      let mut aggregate = 0;\n      let mut unresolvable = 0;\n      let mut gap_count = 0;\n\n      for f in files {\n          let target = root.join(f);\n          match audit_file(&target, root) {\n              Ok(reports) => {\n                  for r in &reports {\n                      total_blocks += 1;\n                      match &r.kind {\n                          ReportKind::Clean => clean += 1,\n                          ReportKind::Drift { diff } => {\n                              drift += 1;\n                              println!(\"[DRIFT]        {} {}: {}\", f, r.spec_ref, diff);\n                          }\n                          ReportKind::Aggregate => aggregate += 1,\n                          ReportKind::Unresolvable { reason } => {\n                              unresolvable += 1;\n                              println!(\"[UNRESOLVABLE] {} {}: {}\", f, r.spec_ref, reason);\n                          }\n                      }\n                  }\n              }\n              Err(e) => eprintln!(\"[ERROR] audit_file {}: {}\", f, e),\n          }\n\n          match audit_markers(&target) {\n              Ok(gaps) => {\n                  gap_count += gaps.len();\n                  for g in &gaps {\n                      println!(\n                          \"[GAP]          {}:{} in {} — item `{}`\",\n                          f, g.line_no, g.enclosing_spec_ref, g.item_line\n                      );\n                  }\n              }\n              Err(e) => eprintln!(\"[ERROR] audit_markers {}: {}\", f, e),\n          }\n      }\n\n      println!(\n          \"{} blocks: {} clean, {} drift, {} aggregate, {} unresolvable; {} marker gaps\",\n          total_blocks, clean, drift, aggregate, unresolvable, gap_count,\n      );\n```\n\n## Changes\n<!-- type: changes lang: yaml -->\n\n```yaml\nchanges:\n  - path: apps/agentic-workflow/examples/audit_smoke.rs\n    action: create\n    section: tests\n    impl_mode: codegen\n    description: |\n      Generate the complete audit smoke example from the Tests template. The\n      template uses `test: false` and an explicit empty attributes list to emit\n      a normal `fn main` harness instead of a `#[test]`.\n```\n"
